def posterior(prior, lik_pos, lik_neg):
    pay = prior * lik_pos
    return pay / (pay + (1 - prior) * lik_neg)

print(round(posterior(0.60, 0.30, 0.02), 4))
print(round(posterior(0.001, 0.99, 0.02), 4))

import math

def poisson(k, lam):
    return lam**k * math.exp(-lam) / math.factorial(k)

def hyper(k, N, K, n):
    return math.comb(K, k) * math.comb(N - K, n - k) / math.comb(N, n)

print(round(poisson(0, 3), 4))
print(round(poisson(3, 2), 4))
print(round(hyper(1, 20, 5, 4), 4))
print(round(hyper(0, 20, 5, 4), 4))
